mapper.sql:
 from cynexus_appl_market.futures_position_member_rank m
 join cynexus_appl_market.futures_position_capture_batch b
   on b.id = m.capture_batch_id
  and b.deleted_at is null
  and b.selected is true
  and b.status in ('SUCCEEDED', 'PARTIAL')
where m.deleted_at is null
  and m.trade_date = #{tradeDate}

    and m.scope_type = #{scopeType}


    and m.exchange_code = #{exchangeCode}


    and m.variety_code = #{varietyCode}

mapper.select:
with facts as ( select m.instrument_code, m.variety_code, m.contract_code, m.rank_type, m.rank_no, m.rank_value, m.rank_change, m.selected_source
), aggregated as ( select instrument_code, max(variety_code) as variety_code, max(contract_code) as contract_code, sum(rank_value) filter (where rank_type = 'VOLUME' and rank_no <= #{top}) as volume, sum(rank_value) filter (where rank_type = 'LONG' and rank_no <= #{top}) as long_position, sum(rank_value) filter (where rank_type = 'SHORT' and rank_no <= #{top}) as short_position, sum(rank_change) filter (where rank_type = 'LONG' and rank_no <= #{top}) as long_change, sum(rank_change) filter (where rank_type = 'SHORT' and rank_no <= #{top}) as short_change, max(selected_source) as source from facts group by instrument_code ) select instrument_code, variety_code, contract_code, volume, long_position, short_position, long_position - short_position as net_position, long_position / nullif(short_position, 0) as long_short_ratio, long_change, short_change, source from aggregated order by
volume long_position short_position long_position / nullif(short_position, 0) instrument_code long_position - short_position
asc nulls last desc nulls last
, instrument_code asc offset #{offset} limit #{limit}

select m.trade_date, m.exchange_code, m.scope_type, m.instrument_code, m.variety_code,
       m.contract_code, m.rank_type, m.rank_no, m.member_name, m.rank_value, m.rank_change,
       m.selected_source as source
  from cynexus_appl_market.futures_position_member_rank m
  join cynexus_appl_market.futures_position_capture_batch b
    on b.id = m.capture_batch_id
   and b.deleted_at is null
   and b.selected is true
   and b.status in ('SUCCEEDED', 'PARTIAL')
 where m.deleted_at is null
   and m.trade_date = #{tradeDate}
   and m.scope_type = #{scopeType}
   and m.exchange_code = #{exchangeCode}
   and m.instrument_code = #{instrumentCode}
   and m.rank_no <= #{top}

   and m.rank_type = #{rankType}

 order by m.rank_type asc, m.rank_no asc, m.member_name asc nulls last
